Who directed more movies, Akira Kurosawa.code:
import requests

def get_director_movie_count(director_name):
    url = "https://api.themoviedb.org/3/search/person"
    params = {
        "api_key": "your_api_key_here",
        "query": director_name
    }
    response = requests.get(url, params=params)
    data = response.json()
    if data['results']:
        director_id = data['results'][0]['id']
        url_credits = f"https://api.themoviedb.org/3/person/{director_id}/movie_credits"
        response_credits = requests.get(url_credits, params={"api_key": "your_api_key_here"})
        credits_data = response_credits.json()
        directed_movies = [movie for movie in credits_data.get('crew', []) if movie.get('job') == 'Director']
        return len(directed_movies)
    return 0

kurosawa_movies = get_director_movie_count("Akira Kurosawa")
spielberg_movies = get_director_movie_count("Steven Spielberg")

if kurosawa_movies > spielberg_movies:
    print("Akira Kurosawa directed more movies.")
elif spielberg_movies > kurosawa_movies:
    print("Steven Spielberg directed more movies.")
else:
    print("Both directed the same number of movies.")

